# 54_fig3_figS4_v136.R  Script 37b with the height curve panel drawn from the joint curve of J1 by origin and the height increment panel from J1 and the rule with the joint curve.
dir.create("~/jobs/koa_final_eq_20261110/ms_v136", showWarnings = FALSE)
# 37b_fig3_figS4_v135.R (37 with the v135 theme: 9 pt type floor, bold axis titles, one origin legend)
# 37_fig3_figS4.R  Fig. 3 in the order of the methods (stand-level equation first) and Fig. S4, for manuscript v134 (November 14, 2026).
# Fig. 3: (a) maximum SDI on BYI, (b) height on DBH, (c) crown ratio on competition, (d) diameter increment on competition, (e) height increment by
# height class (observed, fitted form, Fallback rule), (f) mortality on relative density. Fig. S4: (a) diameter increment on DBH, (b) mortality on DBH,
# (c) crown base held out, (d) height increment held out by interval length. Bands are 95% from plot-cluster bootstraps. No fitting.
suppressMessages({library(data.table); library(ggplot2); library(patchwork)}); source("~/jobs/koa_final_eq_20261110/scripts/32_common.R"); dir.create("ms_v136", showWarnings = FALSE)
L33 <- readLines("scripts/33b_height_increment_round2.R"); i0 <- grep("^suppressMessages", L33); i1 <- grep("^FH <- parallel", L33); eval(parse(text = L33[(i0 + 1):(i1 - 1)]))   # frame, yearly paths, forms
CB <- readRDS("out/crown_base_34.rds"); thJ <- unlist(readRDS("out/height_increment_44.rds")$FF$J1$th); BJ <- readRDS("out/boot_round4_45.rds")$J1; BJ <- BJ[BJ[, "conv"] == 0, ]; kh <- function(th, d, byi) 1.37 + (exp(th[[1]] + th[[2]] * log(byi)) - 1.37) * (1 - exp(-exp(th[[7]]) * d))^exp(th[[8]]); cat("height increment drawn: J1 (adopted); height curve: joint curve of J1 at the median BYI of each origin\n")
OR <- c(Natural = "#0072B2", Planted = "#D55E00"); orig <- function(p) factor(ifelse(p == 1, "Planted", "Natural"), levels = names(OR))
theme_koa <- function() theme_classic(base_size = 11) + theme(axis.text = element_text(colour = "black", size = 9), axis.title = element_text(face = "bold", size = 9.5), legend.position = "bottom", legend.title = element_blank(), legend.text = element_text(size = 9), legend.key.size = unit(4, "mm"), plot.tag = element_text(face = "bold", size = 11), strip.background = element_blank(), strip.text = element_text(face = "bold", size = 10), plot.margin = margin(9, 6, 3, 3))
band <- function(fun, Mx, grid) { m <- apply(Mx, 1, function(b) fun(b, grid)); data.table(lo = apply(m, 1, quantile, .025, na.rm = TRUE), hi = apply(m, 1, quantile, .975, na.rm = TRUE)) }
g4 <- function(b, d) exp(b[[1]] + b[[2]] * log(d$dbh + 1) + b[[3]] * d$dbh + b[[4]] * d$x + b[[5]] * log(d$byi) + b[[6]] * d$pl); g6 <- function(b, d) 1 - exp(-exp(b[[1]] + b[[2]] * log(d$dbh + 1) + b[[3]] * d$dbh + b[[4]] * d$dbh^2 + b[[5]] * d$bal + b[[6]] * log(d$rd) + b[[7]] * log(d$byi) + b[[8]] * d$pl)); gs <- function(b, d) exp(b[[1]] + b[[2]] * log(d$byi) + b[[3]] * d$pl)
mk <- function(xname, xs, fun, Mx, est) rbindlist(lapply(c(0, 1), function(p) { d <- data.table(dbh = 15, x = 0.25, bal = 10, rd = 0.5, byi = byiq[planted == p, md], pl = p)[rep(1, length(xs))]; d[[xname]] <- xs; cbind(data.table(x = xs, origin = orig(p), y = fun(est, d)), band(fun, Mx, d)) }))
lp <- function(d, xl, yl) ggplot(d, aes(x, y, colour = origin, fill = origin)) + geom_ribbon(aes(ymin = lo, ymax = hi), alpha = 0.25, colour = NA) + geom_line(linewidth = 0.6) + scale_colour_manual(values = OR, drop = FALSE) + scale_fill_manual(values = OR, drop = FALSE) + labs(x = xl, y = yl)
yi <- "Diameter increment (cm yr⁻¹)"; ym <- "Annual mortality probability"
pS <- lp(mk("byi", seq(60, 450, length.out = 80), gs, K[, kS], bs), "BYI (Mg ha⁻¹)", "Maximum SDI (trees ha⁻¹)") + geom_point(data = M[, .(x = BYI, y = smax, origin = orig(planted))], aes(x, y, colour = origin), inherit.aes = FALSE, size = 0.3, alpha = 0.35, show.legend = FALSE) + coord_cartesian(ylim = c(0, 2500))
hd <- f$hd; xs <- seq(1, 100, length.out = 120); h1 <- rbindlist(lapply(c(0, 1), function(p) { by <- byiq[planted == p, md]; m <- apply(BJ, 1, function(b) kh(b, xs, by)); data.table(origin = orig(p), x = xs, y = kh(thJ, xs, by), lo = apply(m, 1, quantile, 0.025), hi = apply(m, 1, quantile, 0.975)) }))
pH <- ggplot() + geom_point(data = hd[DBH <= 100], aes(DBH, HT, colour = orig(planted)), size = 0.25, alpha = 0.25, show.legend = FALSE) + geom_ribbon(data = h1, aes(x, ymin = lo, ymax = hi, fill = origin), alpha = 0.35, show.legend = FALSE) + geom_line(data = h1, aes(x, y, colour = origin), linewidth = 0.6, show.legend = FALSE) + scale_colour_manual(values = OR) + scale_fill_manual(values = OR) + labs(x = "DBH (cm)", y = "Total height (m)")
# crown ratio on competition, natural trees only (the crown records)
hc <- fread("~/jobs/koa_v105final_20261103/frames/final/AK_HCB_v103.csv"); hc[, pid := paste(Data, Install, Plot, sep = "|")]; cd <- merge(hc[, .(pid, Tree = as.character(Tree), Measure = INVYR, HCB)], tr[, .(pid, Tree = as.character(Tree), Measure, DBH, HT, BAL, BA_koa, SDI_koa, BYI, planted)], by = c("pid", "Tree", "Measure")); cd[, `:=`(x = BAL / pmax(BA_koa, 1e-6) * SDI_koa / SM[pid], cr = 1 - HCB / HT)]
tm <- CB$TM[[CB$pick]]; crf <- function(b, d) { z <- data.table(lH = log(d$ht), dh = d$dbh / d$ht, x = d$x, lb = log(d$byi)); 1 - 1 / (1 + exp(as.numeric(cbind(rep(1, nrow(d)), as.matrix(z[, ..tm])) %*% b))) }
cg <- rbindlist(lapply(c(8, 20), function(h) { d <- data.table(ht = h, dbh = pmax((-log(1 - ((h - 1.37) / cf$e2[["a0"]])^(1 / cf$e2[["c"]])) / cf$e2[["b"]]), 2), x = seq(0, 1.1, length.out = 60), byi = byiq[planted == 0, md]); cbind(data.table(x = d$x, hcl = factor(paste0("Height ", h, " m")), y = crf(CB$FC[[CB$pick]], d)), band(crf, CB$boot, d)) }))
CC <- c(`Height 8 m` = "#56B4E9", `Height 20 m` = "#00674C")
pC <- ggplot(cg, aes(x, y)) + geom_point(data = cd, aes(x, cr), inherit.aes = FALSE, colour = OR[["Natural"]], size = 0.3, alpha = 0.35) + geom_ribbon(aes(ymin = lo, ymax = hi, fill = hcl), alpha = 0.25, show.legend = FALSE) + geom_line(aes(colour = hcl), linewidth = 0.6, show.legend = FALSE) + scale_colour_manual(values = CC) + scale_fill_manual(values = CC) +
  annotate("text", x = 1.08, y = c(0.30, 0.20), label = names(CC), colour = CC, hjust = 1, size = 2.5) + coord_cartesian(ylim = c(0, 1)) + labs(x = "(BAL / BA) × relative density", y = "Crown ratio")
pD <- lp(mk("x", seq(0, 1, length.out = 80), g4, K[, kG], bg), "(BAL / BA) × relative density", yi)
# height increment by height class: observed, fitted form, rule (full-frame predictions, each pair weighted as in fitting)
pr1 <- proj(thJ[1:6], G$B2); pr0 <- proj(thJ, function(th, H, D, D1, x, lb, pl) kh(th, D1, exp(lb)) - kh(th, D, exp(lb))); hb <- data.table(origin = orig(prs$planted), hc = cut(prs$H0, c(1.37, seq(4, 28, 3), 40), include.lowest = TRUE), H0 = prs$H0, w = prs$w0, obs = prs$adh, fit = (pr1$end - prs$H0) / prs$yip, rule = (pr0$end - prs$H0) / prs$yip)
hs <- hb[, .(n = .N, x = sum(w * H0) / sum(w), obs = sum(w * obs) / sum(w), fit = sum(w * fit) / sum(w), rule = sum(w * rule) / sum(w)), by = .(origin, hc)][n >= 15]
pI <- ggplot(hs, aes(x, colour = origin)) + geom_point(aes(y = obs), size = 1.1) + geom_line(aes(y = fit), linewidth = 0.6) + geom_line(aes(y = rule), linewidth = 0.5, linetype = "22") + scale_colour_manual(values = OR, drop = FALSE) + labs(x = "Height at start (m)", y = "Height increment (m yr⁻¹)") + guides(colour = "none")
pM <- lp(mk("rd", seq(0.05, 1.2, length.out = 80), g6, K[, kM], bm), "Relative density", ym)
fig3 <- (pS + pH + pC + pD + pI + pM) + plot_layout(ncol = 3, guides = "collect") + plot_annotation(tag_levels = "a", tag_prefix = "(", tag_suffix = ")") & theme_koa(); ggsave("ms_v136/Fig3_equations.png", fig3, width = 180, height = 135, units = "mm", dpi = 300, type = "cairo")
# Fig. S4
pb <- lp(mk("dbh", seq(2, 80, length.out = 80), g4, K[, kG], bg), "DBH (cm)", yi); pe <- lp(mk("dbh", seq(2, 100, length.out = 99), g6, K[, kM], bm), "DBH (cm)", ym) + scale_y_log10()
cvc <- CB$cv[form == CB$pick]; pc2 <- ggplot(cvc, aes(pred, obs)) + annotate("ribbon", x = c(0, 18), ymin = c(0, 0.75 * 18), ymax = c(0, 1.25 * 18), fill = "#56B4E9", alpha = 0.25) + geom_abline(slope = 1, intercept = 0, linewidth = 0.3, colour = "#0072B2") + geom_point(size = 0.5, alpha = 0.5, colour = OR[["Natural"]]) + coord_cartesian(xlim = c(0, 18), ylim = c(0, 18), expand = FALSE) + labs(x = "Predicted crown base, held out (m)", y = "Observed crown base (m)")
cb52 <- readRDS("out/j1_eval_52.rds")$cb; cvh <- rbind(cb52[, .(form = "R0", planted, ylen, obs, pred = pR)], cb52[, .(form = "J1", planted, ylen, obs, pred = pJ)]); cvh[, `:=`(origin = orig(planted), what = ifelse(form == "R0", "Fallback rule", "Equation E5"))]; ch <- cvh[, .(bias = mean(obs - pred), rmse = sqrt(mean((obs - pred)^2))), by = .(what, origin, ylen)]
pd2 <- ggplot(ch, aes(ylen, rmse, colour = origin, shape = what, group = interaction(origin, what))) + geom_line(aes(linetype = what), linewidth = 0.5) + geom_point(size = 1.4) + scale_colour_manual(values = OR, drop = FALSE) + scale_shape_manual(values = c(`Fallback rule` = 1, `Equation E5` = 16)) + scale_linetype_manual(values = c(`Fallback rule` = "22", `Equation E5` = "solid")) + labs(x = "Interval length (yr)", y = "RMSE of height increment (m yr⁻¹)") + guides(colour = "none")
figS4 <- (pb + pe + pc2 + pd2) + plot_layout(ncol = 2, guides = "collect") + plot_annotation(tag_levels = "a", tag_prefix = "(", tag_suffix = ")") & theme_koa(); ggsave("ms_v136/FigS4_more_responses.png", figS4, width = 170, height = 160, units = "mm", dpi = 300, type = "cairo")
